'use strict';
(function(){
const C=window.RepairCore,S=window.RepairStore,I=window.RepairI18n,host=window.repairHost;
const L=window.Repair={page:'home',orderId:'',settingsTab:'general',license:{plan:'free',status:'inactive',limits:C.planLimits('free'),activated:false,storageAvailable:false},T:I.T};
const NAV=[['home','home'],['orders','orders'],['parts','parts'],['timeline','timeline'],['reports','reports'],['plans','plans'],['settings','settings']];
const PATH={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',orders:'<rect x="4" y="4" width="16" height="16" rx="3"/><path d="M8 8h8M8 12h5M8 16h3"/>',parts:'<path d="m3 7 9-4 9 4-9 4zM3 7v10l9 4 9-4V7M12 11v10"/>',timeline:'<path d="M4 5v14M4 7h5l3 5h8M4 17h5l3-5"/><circle cx="4" cy="5" r="1"/><circle cx="20" cy="12" r="1"/><circle cx="4" cy="19" r="1"/>',reports:'<path d="M4 19V9m6 10V5m6 14v-7m4 7H2"/>',plans:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18m-13 5h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.1.9-1.2 2.1-1.4-.5-.2.1a8 8 0 0 1-1.4.8l-.2.1-.2 1.5h-2.4l-.2-1.5-.2-.1a8 8 0 0 1-1.4-.8l-.2-.1-1.4.5-1.2-2.1 1.1-.9.1-.1a8 8 0 0 1 0-1.6l-.1-.1-1.1-.9 1.2-2.1 1.4.5.2-.1a8 8 0 0 1 1.4-.8l.2-.1.2-1.5h2.4l.2 1.5.2.1a8 8 0 0 1 1.4.8l.2.1 1.4-.5 1.2 2.1-1.1.9-.1.1a8 8 0 0 1 0 1.6z"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M7 10V7a5 5 0 0 1 10 0v3"/>',arrow:'<path d="M19 12H5m7 7-7-7 7-7"/>',check:'<path d="m5 12 5 5L20 7"/>',print:'<path d="M6 8V3h12v5M6 17H4a2 2 0 0 1-2-2v-4a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2h-2M6 14h12v7H6z"/>',external:'<path d="M13 4h7v7m0-7-9 9"/><path d="M18 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h5"/>',box:'<path d="m12 3 9 5-9 5-9-5 9-5zm-9 5v9l9 5 9-5V8m-9 5v9"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="m12 3 10 18H2L12 3z"/><path d="M12 9v5m0 3v.1"/>'};
L.icon=(n,cls='ico')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${PATH[n]||''}</svg>`;
L.lang=()=>S.state.settings.lang;L.t=(k,v={})=>I.t(k,L.lang(),v);L.esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LOC={es:'es-AR',en:'en-US',pt:'pt-BR',fr:'fr-FR'};
L.date=v=>{try{return new Date(v).toLocaleString(LOC[L.lang()],{dateStyle:'medium',timeStyle:'short'})}catch{return v||''}};
L.money=v=>{try{return new Intl.NumberFormat(LOC[L.lang()],{style:'currency',currency:S.state.shop.currency||'ARS',maximumFractionDigits:2}).format(Number(v)||0)}catch{return `${Number(v||0).toFixed(2)} ${S.state.shop.currency||'ARS'}`}};
const statKey={received:'received',diagnosing:'diagnosing','waiting-approval':'waitingApproval','waiting-parts':'waitingParts',repairing:'repairing','quality-check':'qualityCheck',ready:'readyStatus',delivered:'delivered',cancelled:'cancelled'};
const catKey={phone:'devicePhone',computer:'deviceComputer',console:'deviceConsole',tablet:'deviceTablet',appliance:'deviceAppliance',audio:'deviceAudio',other:'deviceOther'};
L.status=v=>L.t(statKey[v]||'received');L.category=v=>catKey[v]?L.t(catKey[v]):String(v||L.t('deviceOther'));
L.order=id=>S.state.orders.find(o=>o.id===id);L.save=()=>S.touch();
L.loadLicense=async()=>{try{L.license=await host.license.info()}catch{}return L.license};host.license.onChanged(info=>{const pendingCode=document.querySelector('#license-form [name=code]')?.value||'';L.license=info;if(S.state){L.render();const input=document.querySelector('#license-form [name=code]');if(input&&pendingCode)input.value=pendingCode;const notice={expired:'licenseExpired','needs-online':'licenseNeedsOnline','clock-check':'licenseClock','update-required':'licenseUpdateRequired'}[info.status];if(notice)L.toast(L.t(notice))}});
L.toast=msg=>{const e=document.createElement('div');e.className='toast-item';e.textContent=msg;document.getElementById('toast').append(e);setTimeout(()=>e.remove(),3600)};host.account.onGoogleError(status=>{if(status)L.toast(L.t(status==='cancelled'?'googleCancelled':status==='expired'?'googleExpired':'googleFailed'))});
L.err=e=>{const map={'required-fields':L.t('required'),'invalid-backup':L.t('invalidBackup'),'backup-too-large':L.t('error'),'quote-lines':L.t('error'),'quote-description':L.t('error'),'correction-fields':L.t('reason'),'stock-insufficient':L.t('error'),'plan-active-order-limit':L.t('limitReached'),'plan-parts-limit':L.t('limitReached'),'weak-backup-pass':L.t('licenseInvalid'),'password-mismatch':L.t('passwordMismatch'),'account-fields-invalid':L.t('accountFieldsInvalid'),'account-confirmation':L.t('accountConfirmation'),'account-terms-required':L.t('accountTermsRequired'),'Correo o contraseña incorrectos.':L.t('invalidCredentials'),'Demasiados intentos. Esperá unos minutos e intentá de nuevo.':L.t('tryLater')};return map[e?.message]||L.t('error')};
L.modal=(title,body,buttons=[])=>{const d=document.getElementById('modal');document.getElementById('modal-title').textContent=title;document.getElementById('modal-body').innerHTML=body;const foot=document.getElementById('modal-foot'),formId=body.match(/<form[^>]*id="([^"]+)"/)?.[1]||'';foot.innerHTML='';for(const b of buttons){const el=document.createElement('button');el.className=`btn ${b.primary?'primary':''} ${b.danger?'danger':''}`;el.type=b.submit?'submit':'button';if(b.submit&&formId)el.setAttribute('form',formId);el.textContent=b.label;el.dataset.modalAction=b.action||'';foot.append(el)}d.showModal();setTimeout(()=>d.querySelector('#modal-body input, #modal-body select, #modal-body textarea, #modal-foot button')?.focus(),20);};
L.close=()=>document.getElementById('modal').close();
L.applyPrefs=()=>{const s=S.state.settings,root=document.documentElement;let dark=s.theme==='dark';if(s.theme==='system')dark=matchMedia('(prefers-color-scheme: dark)').matches;root.dataset.theme=dark?'dark':'light';root.dataset.motion=s.motion;root.lang=s.lang;document.title=`Koluva Repair${S.state.shop.name?' · '+S.state.shop.name:''}`;document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===s.theme)));};
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(S.state&&S.state.settings.theme==='system')L.applyPrefs()});
L.motionOn=()=>{const m=S.state.settings.motion;return m==='on'||(m==='system'&&!matchMedia('(prefers-reduced-motion: reduce)').matches)};
L.opening=async()=>{const s=S.state.settings;if(!s.opening||!L.motionOn()||!window.KolivaIntro)return;await window.KolivaIntro.play({iso:'assets/koluva-repair-isotipo-white.svg',pattern:'assets/koluva-isotipo-pattern.svg',color:'#8A0F24',duration:2000});};
L.renderNav=()=>{document.getElementById('nav').innerHTML=NAV.map(([page,key],i)=>`<button class="nav-item" data-page="${page}" aria-current="${L.page===page?'page':'false'}" aria-keyshortcuts="${i+1}">${L.icon(page)}<span>${L.t(key)}</span></button>`).join('');document.getElementById('side-foot').innerHTML=`<div class="local-tag">${L.icon('lock')}<span>${L.t('localOnly')}</span></div>`;};
L.go=(page,orderId='')=>{L.page=page;L.orderId=orderId;L.render();document.getElementById('main').focus({preventScroll:true});};
L.mainHead=(title,sub,actions='')=>`<div class="head"><div><h1>${L.esc(title)}</h1>${sub?`<p>${L.esc(sub)}</p>`:''}</div><div class="head-actions">${actions}</div></div>`;
L.chartWeek=()=>{const data=C.stats(S.state).week,max=Math.max(1,...data.map(x=>x.count)),x0=34,y0=156,w=510,h=120;const points=data.map((x,i)=>[x0+i*w/6,y0-(x.count/max)*h]);const d=points.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ');return `<svg class="chart" viewBox="0 0 590 190" role="img" aria-label="${L.t('week')}"><path class="grid-line" d="M30 36H570M30 96H570M30 156H570"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" fill="var(--red)"/><text x="${p[0]}" y="178" text-anchor="middle">${L.esc(new Date(data[i].day+'T12:00:00').toLocaleDateString(LOC[L.lang()],{weekday:'short'}))}</text>`).join('')}<path class="series" d="${d}"/></svg>`;};
L.statusChart=()=>{const s=C.stats(S.state),items=[['received',S.state.orders.filter(o=>o.status==='received').length],['diagnosing',S.state.orders.filter(o=>o.status==='diagnosing').length],['waitingApproval',S.state.orders.filter(o=>o.status==='waiting-approval').length],['waitingParts',S.state.orders.filter(o=>o.status==='waiting-parts').length],['repairing',S.state.orders.filter(o=>['repairing','quality-check'].includes(o.status)).length],['readyStatus',s.ready]],max=Math.max(1,...items.map(x=>x[1]));return `<div class="urgent-list">${items.map(([k,n],i)=>`<div class="status-bar-row" style="--row:${i}"><span>${L.t(k)}</span><div class="status-track"><i style="--status-scale:${(n/max).toFixed(3)}"></i></div><strong>${n}</strong></div>`).join('')}</div>`;};
L.homePage=()=>{const s=C.stats(S.state),active=S.state.orders.filter(o=>!['delivered','cancelled'].includes(o.status));const urgent=active.filter(o=>o.priority==='urgent'||o.dueDate&&o.dueDate<new Date().toISOString().slice(0,10)||['waiting-approval','waiting-parts'].includes(o.status)).slice(0,5);const stats=[['active',s.active,Math.min(1,s.active/20)],['ready',s.ready,Math.min(1,s.ready/8)],['waiting',s.waiting,Math.min(1,s.waiting/10)],['overdue',s.overdue,Math.min(1,s.overdue/6)]];return `<section class="page">${L.mainHead(S.state.shop.name||L.t('home'),new Date().toLocaleDateString(LOC[L.lang()],{weekday:'long',day:'numeric',month:'long'}),`<button class="btn primary" data-action="new-order">${L.icon('plus')}${L.t('newOrder')}</button>`)}<div class="grid">${stats.map(([key,n,p])=>`<article class="card span-3 metric"><svg class="ring" viewBox="0 0 40 40" role="img" aria-label="${L.esc(L.t(key))} ${n}"><circle cx="20" cy="20" r="16" pathLength="100"/><circle class="progress" cx="20" cy="20" r="16" pathLength="100" style="--offset:${100-p*100}"/></svg><div><div class="metric-label">${L.t(key)}</div><div class="metric-value">${n}</div></div></article>`).join('')}<article class="card span-8"><div class="section-title"><h3>${L.t('week')}</h3><button class="btn small ghost" data-page="reports">${L.t('reports')}</button></div>${L.chartWeek()}</article><article class="card span-4"><div class="section-title"><h3>${L.t('attention')}</h3><button class="btn small ghost" data-page="orders">${L.t('all')}</button></div>${urgent.length?`<div class="urgent-list">${urgent.map(o=>`<div class="urgent-row" data-order="${o.id}" tabindex="0"><i class="dot"></i><div><strong>${L.esc(o.ticket)} — ${L.esc(o.device.model||o.device.brand||L.category(o.device.category))}</strong><span class="sub">${L.esc(o.customer.name)} · ${L.status(o.status)}</span></div>${L.icon('arrow')}</div>`).join('')}</div>`:`<div class="empty compact"><h3>${L.t('noActive')}</h3><p>${L.t('startOrder')}</p></div>`}</article><article class="card span-7"><div class="section-title"><h3>${L.t('status')}</h3><button class="btn small ghost" data-page="timeline">${L.t('timeline')}</button></div>${L.statusChart()}</article><article class="card span-5"><h3>${L.t('quick')}</h3><div class="quick-actions"><button class="btn primary" data-action="new-order">${L.icon('plus')}${L.t('newOrder')}</button><button class="btn" data-page="parts">${L.icon('parts')}${L.t('parts')}</button><button class="btn" data-page="timeline">${L.icon('timeline')}${L.t('timeline')}</button></div><div class="local-banner" style="margin-top:18px">${L.icon('lock')}<span>${L.t('localOnly')}</span></div></article></div></section>`;};
L.orderRows=(list)=>list.map(o=>`<tr class="click-row" data-order="${o.id}" tabindex="0"><td><span class="ticket-code">${L.esc(o.ticket)}</span></td><td><strong>${L.esc(o.customer.name)}</strong><div class="muted small">${L.esc(o.customer.contact)}</div></td><td>${L.esc(L.category(o.device.category))}<div class="muted small">${L.esc([o.device.brand,o.device.model].filter(Boolean).join(' '))}</div></td><td><span class="chip ${['urgent','high'].includes(o.priority)?'red':''}">${L.status(o.status)}</span></td><td>${L.date(o.updatedAt)}</td><td>${o.dueDate?L.esc(o.dueDate):'—'}</td></tr>`).join('');
L.ordersPage=()=>{const list=S.state.orders;const rows=list.length?`<div class="table-wrap"><table><thead><tr><th>${L.t('ticket')}</th><th>${L.t('customer')}</th><th>${L.t('device')}</th><th>${L.t('status')}</th><th>${L.t('updated')}</th><th>${L.t('dueDate')}</th></tr></thead><tbody id="order-rows">${L.orderRows(list)}</tbody></table></div>`:`<div class="empty"><img src="assets/koluva-repair-isotipo-ink.svg" alt=""><h3>${L.t('noOrders')}</h3><p>${L.t('startOrder')}</p><button class="btn primary" data-action="new-order">${L.icon('plus')}${L.t('create')}</button></div>`;return `<section class="page">${L.mainHead(L.t('orders'),`${C.stats(S.state).active} ${L.t('active').toLowerCase()}`,`<label class="search">${L.icon('search')}<input class="input" id="order-search" type="search" placeholder="${L.esc(L.t('search'))}" aria-label="${L.esc(L.t('search'))}"></label><button class="btn primary" data-action="new-order">${L.icon('plus')}${L.t('newOrder')}</button>`)}${rows}</section>`;};
L.orderForm=()=>`<form id="order-form" class="form-grid"><label class="field">${L.t('customerName')}<input class="input" name="customerName" maxlength="100" autocomplete="off" required></label><label class="field">${L.t('contact')}<input class="input" name="customerContact" maxlength="160" autocomplete="off" required></label><label class="field">${L.t('category')}<select class="select" name="category">${S.state.categories.map(x=>`<option value="${L.esc(x)}">${L.esc(L.category(x))}</option>`).join('')}</select></label><label class="field">${L.t('priority')}<select class="select" name="priority"><option value="normal">${L.t('normal')}</option><option value="high">${L.t('high')}</option><option value="urgent">${L.t('urgent')}</option></select></label><label class="field">${L.t('brand')}<input class="input" name="brand" maxlength="100"></label><label class="field">${L.t('model')}<input class="input" name="model" maxlength="120"></label><label class="field">${L.t('serial')}<input class="input" name="serial" maxlength="160"></label><label class="field">${L.t('dueDate')}<input class="input" type="date" name="dueDate"></label><label class="field full">${L.t('condition')}<textarea class="textarea" name="condition" maxlength="1200"></textarea></label><label class="field full">${L.t('accessories')}<input class="input" name="accessories" maxlength="600"></label><label class="field full">${L.t('problem')}<textarea class="textarea" name="problem" maxlength="3000" required></textarea></label><p class="muted small full">${L.t('localOnly')}</p></form>`;
L.openNewOrder=()=>{if(C.stats(S.state).active>=L.license.limits.activeOrders){L.toast(L.t('limitReached'));L.go('plans');return;}L.modal(L.t('newRepair'),L.orderForm(),[{label:L.t('cancel'),action:'close'},{label:L.t('save'),submit:true,primary:true}]);};
L.detailPage=()=>{const o=L.order(L.orderId);if(!o)return L.ordersPage();const last=o.quoteVersions.at(-1),partRows=o.parts.map(x=>`<li>${L.esc(x.name)} — ${x.quantity} × ${L.money(x.unitPrice)}</li>`).join('');return `<section class="page">${L.mainHead('', '', '')}<div class="order-head"><button class="btn back" data-page="orders">${L.icon('arrow')}${L.t('back')}</button><div class="details"><h1>${L.esc(o.ticket)} <span class="chip ${o.priority==='urgent'?'red':''}">${L.status(o.status)}</span></h1><p>${L.esc(o.customer.name)} — ${L.esc(o.device.brand)} ${L.esc(o.device.model)} — ${L.esc(o.customer.contact)}</p></div><button class="btn" data-action="print">${L.icon('print')}${L.t('print')}</button></div><div class="grid"><article class="card span-7"><div class="section-title"><h2>${L.t('details')}</h2><label class="field">${L.t('status')}<select class="select" id="status-select" data-action="status-change">${C.STATUS.map(s=>`<option value="${s}" ${s===o.status?'selected':''}>${L.esc(L.status(s))}</option>`).join('')}</select></label></div><div class="detail-grid"><div><span class="muted small">${L.t('customer')}</span><strong>${L.esc(o.customer.name)}</strong><span>${L.esc(o.customer.contact)}</span></div><div><span class="muted small">${L.t('device')}</span><strong>${L.esc(L.category(o.device.category))} ${L.esc(o.device.brand)} ${L.esc(o.device.model)}</strong><span>${L.esc(o.device.serial)}</span></div><div><span class="muted small">${L.t('problem')}</span><span class="preserve">${L.esc(o.problem)}</span></div><div><span class="muted small">${L.t('condition')}</span><span class="preserve">${L.esc(o.device.condition||'—')}</span></div><div><span class="muted small">${L.t('diagnosis')}</span><span class="preserve">${L.esc(o.diagnosis||'—')}</span></div><div><span class="muted small">${L.t('accessories')}</span><span class="preserve">${L.esc(o.device.accessories||'—')}</span></div></div><div class="section-title"><h3>${L.t('evidence')}</h3><button class="btn small" data-action="attach">${L.icon('plus')}${L.t('attach')}</button></div><div class="attachment-list" id="order-attachments"></div></article><article class="card span-5"><div class="section-title"><h2>${L.t('estimate')}</h2><button class="btn small" data-action="new-quote">${L.icon('plus')}${L.t('addEstimate')}</button></div>${last?`<p class="muted small">v${last.version} — ${L.t(last.status)} — ${L.date(last.createdAt)}</p><h2>${L.money(last.total)}</h2><ul class="print-list">${last.lines.map(x=>`<li>${L.esc(x.description)} — ${x.quantity} × ${L.money(x.unitPrice)}</li>`).join('')}</ul>${last.status==='pending'?`<div class="quick-actions"><button class="btn small" data-action="approve">${L.icon('check')}${L.t('approve')}</button><button class="btn small" data-action="reject">${L.t('reject')}</button></div>`:''}`:`<div class="empty compact"><h3>${L.t('estimate')}</h3><p>${L.t('startOrder')}</p><button class="btn small" data-action="new-quote">${L.t('addEstimate')}</button></div>`}<div class="section-title"><h3>${L.t('partsTitle')}</h3></div>${partRows?`<ul class="print-list">${partRows}</ul>`:`<p class="muted small">${L.t('noParts')}</p>`}<div class="quick-actions"><button class="btn small" data-action="assign-part">${L.t('assignPart')}</button><button class="btn small" data-action="note">${L.t('addNote')}</button><button class="btn small" data-action="correction">${L.t('correction')}</button></div></article><article class="card span-12"><div class="section-title"><h2>${L.t('history')}</h2><span class="chip">${o.events.length}</span></div>${o.events.length?`<div class="timeline">${[...o.events].reverse().map(ev=>`<div class="event"><i class="event-mark"></i><div><h3>${L.esc(ev.title)}</h3>${ev.detail?`<p>${L.esc(ev.detail)}</p>`:''}${ev.extra?.reason?`<p>${L.esc(L.t('reason'))}: ${L.esc(ev.extra.reason)}</p>`:''}<time datetime="${L.esc(ev.at)}">${L.date(ev.at)}</time></div></div>`).join('')}</div>`:`<p class="muted">${L.t('noHistory')}</p>`}</article></div></section>`;};
L.partsPage=()=>{const parts=S.state.parts.filter(p=>!p.archived),low=parts.filter(p=>p.quantity<=p.minimum);return `<section class="page">${L.mainHead(L.t('inventory'),`${parts.length} ${L.t('parts').toLowerCase()}`,`<button class="btn primary" data-action="new-part">${L.icon('plus')}${L.t('addPart')}</button>`)}${low.length?`<div class="local-banner" style="margin-bottom:14px">${L.icon('alert')}<span>${L.t('lowStock')}: ${low.length}</span></div>`:''}${parts.length?`<div class="table-wrap"><table><thead><tr><th>${L.t('sku')}</th><th>${L.t('partName')}</th><th>${L.t('categoryPart')}</th><th>${L.t('stock')}</th><th>${L.t('minimum')}</th><th>${L.t('cost')}</th><th>${L.t('price')}</th></tr></thead><tbody>${parts.map(p=>`<tr><td>${L.esc(p.sku||'—')}</td><td><strong>${L.esc(p.name)}</strong></td><td>${L.esc(p.category||'—')}</td><td><span class="chip ${p.quantity<=p.minimum?'red':''}">${p.quantity}</span></td><td>${p.minimum}</td><td>${L.money(p.cost)}</td><td>${L.money(p.price)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><img src="assets/koluva-repair-isotipo-ink.svg" alt=""><h3>${L.t('noParts')}</h3><button class="btn primary" data-action="new-part">${L.icon('plus')}${L.t('addPart')}</button></div>`}</section>`;};
L.timelinePage=()=>{const events=S.state.orders.flatMap(o=>o.events.map(e=>({order:o,event:e}))).sort((a,b)=>b.event.at.localeCompare(a.event.at)).slice(0,100);return `<section class="page">${L.mainHead(L.t('timeline'),L.t('history'))}<article class="card">${events.length?`<div class="timeline">${events.map(({order,event:e})=>`<div class="event"><i class="event-mark"></i><div><h3>${L.esc(e.title)} <button class="linklike" data-order="${order.id}">${L.esc(order.ticket)}</button></h3><p>${L.esc(order.customer.name)}${e.detail?` — ${L.esc(e.detail)}`:''}</p><time>${L.date(e.at)}</time></div></div>`).join('')}</div>`:`<div class="empty"><h3>${L.t('noHistory')}</h3></div>`}</article></section>`;};
L.reportsPage=()=>{const s=C.stats(S.state),byStatus=C.STATUS.map(k=>({k,n:S.state.orders.filter(o=>o.status===k).length}));return `<section class="page">${L.mainHead(L.t('reports'),L.t('week'))}<div class="grid"><article class="card span-7"><h3>${L.t('week')}</h3>${L.chartWeek()}</article><article class="card span-5"><h3>${L.t('status')}</h3>${L.statusChart()}</article><article class="card span-12"><h3>${L.t('orders')}</h3><div class="report-grid">${byStatus.map(x=>`<div class="report-item"><span>${L.status(x.k)}</span><strong>${x.n}</strong></div>`).join('')}</div><p class="muted small">${L.t('localOnly')}</p></article></div></section>`;};
L.plansPage=()=>{const current=L.license.plan||'free',limit=L.license.limits||C.planLimits('free'),limitText=n=>Number.isFinite(n)?String(n):L.t('unlimited');const stateKey={inactive:'licenseInactive',active:'licenseActive',offline:'licenseOffline',expired:'licenseExpired','needs-online':'licenseNeedsOnline','clock-check':'licenseClock','update-required':'licenseUpdateRequired',invalid:'licenseInvalid'}[L.license.status]||'licenseInactive';return `<section class="page">${L.mainHead(L.t('plansTitle'),L.t('manualRenew'))}<div class="local-banner" style="margin-bottom:16px">${L.icon('lock')}<span>${L.t(stateKey)} ${L.esc(L.t('accountOptional'))}</span></div>${L.license.daysLeft!==null&&L.license.daysLeft<=7&&L.license.daysLeft>=0?`<div class="local-banner license-reminder">${L.icon('clock')}<span>${L.t(L.license.daysLeft===0?'licenseToday':'licenseDays',{days:L.license.daysLeft})} · ${L.esc(L.t('renewalSoon'))}</span>${L.license.contact?.email?`<button class="btn small" data-action="license-contact">${L.t('renewal')}</button>`:''}</div>`:''}<div class="plan-grid"><article class="plan-card ${current==='free'?'featured':''}"><h3>${L.t('free')}</h3><p>${L.t('freeDesc')}</p><ul>${[`${L.t('limitActive')}: ${limitText(C.planLimits('free').activeOrders)}`,`${L.t('limitParts')}: ${limitText(C.planLimits('free').parts)}`,L.t('allFormats')].map(x=>`<li>${L.icon('check')}${L.esc(x)}</li>`).join('')}</ul><span class="chip" style="margin-top:18px">${current==='free'?L.t('licenseActive'):L.t('free')}</span></article><article class="plan-card ${current==='repair-pro'?'featured':''}"><h3>${L.t('pro')}</h3><p>${L.t('proDesc')}</p><ul><li>${L.icon('check')}${L.esc(L.t('proBenefit'))}</li><li>${L.icon('check')}${L.esc(L.t('allFormats'))}</li></ul><button class="btn ${current==='repair-pro'?'primary':''}" style="margin-top:18px" data-action="contact">${L.t('contactKoluva')}</button></article><article class="plan-card ${current==='repair-pro-plus'?'featured':''}"><h3>${L.t('proPlus')}</h3><p>${L.t('proPlusDesc')}</p><ul><li>${L.icon('check')}${L.esc(L.t('plusBenefit'))}</li><li>${L.icon('check')}${L.esc(L.t('allFormats'))}</li></ul><button class="btn ${current==='repair-pro-plus'?'primary':''}" style="margin-top:18px" data-action="contact">${L.t('contactKoluva')}</button></article></div><p class="muted small" style="margin-top:16px">${L.t('manualRenew')} ${L.t('priceContact')}</p></section>`;};L.settingsPage=()=>{const s=S.state.settings,shop=S.state.shop,tab=L.settingsTab;return `<section class="page">${L.mainHead(L.t('settingsTitle'),L.t('localOnly'))}<div class="settings-grid"><nav class="settings-nav" aria-label="${L.t('settingsTitle')}"><button data-settings-tab="general" aria-current="${tab==='general'}">${L.t('settingsTitle')}</button><button data-settings-tab="shop" aria-current="${tab==='shop'}">${L.t('shop')}</button><button data-settings-tab="subscription" aria-current="${tab==='subscription'}">${L.t('subscriptionTab')}</button><button data-settings-tab="data" aria-current="${tab==='data'}">${L.t('backup')}</button><button data-settings-tab="updates" aria-current="${tab==='updates'}">${L.t('checkUpdate')}</button></nav><article class="card">${tab==='general'?`<form id="general-settings" class="form-grid"><label class="field">${L.t('language')}<select name="lang" class="select">${[['es','Español'],['en','English'],['fr','Français'],['pt','Português']].map(([v,n])=>`<option value="${v}" ${s.lang===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">${L.t('theme')}<select name="theme" class="select"><option value="system" ${s.theme==='system'?'selected':''}>${L.t('system')}</option><option value="light" ${s.theme==='light'?'selected':''}>${L.t('light')}</option><option value="dark" ${s.theme==='dark'?'selected':''}>${L.t('dark')}</option></select></label><label class="field">${L.t('motion')}<select name="motion" class="select"><option value="system" ${s.motion==='system'?'selected':''}>${L.t('automatic')}</option><option value="on" ${s.motion==='on'?'selected':''}>${L.t('on')}</option><option value="off" ${s.motion==='off'?'selected':''}>${L.t('off')}</option></select></label><label class="field">${L.t('currency')}<select name="currency" class="select">${['ARS','USD','EUR','BRL','MXN','CLP','UYU'].map(x=>`<option ${shop.currency===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="check full"><input type="checkbox" name="opening" ${s.opening?'checked':''}>${L.t('opening')}</label><label class="check full"><input type="checkbox" name="autoUpdate" ${s.autoUpdate?'checked':''}>${L.t('autoUpdate')}</label><div class="full"><button class="btn primary" type="submit">${L.t('saveSettings')}</button></div></form>`:tab==='shop'?`<form id="shop-settings" class="form-grid"><label class="field">${L.t('shopName')}<input class="input" name="name" maxlength="120" value="${L.esc(shop.name)}"></label><label class="field">${L.t('shopType')}<select class="select" name="kind">${['repair-shop','phone-repair','computer-repair','console-repair','general-repair'].map(x=>`<option value="${x}" ${shop.kind===x?'selected':''}>${x.replaceAll('-',' ')}</option>`).join('')}</select></label><label class="field">${L.t('phone')}<input class="input" name="phone" maxlength="80" value="${L.esc(shop.phone)}"></label><label class="field">${L.t('email')}<input class="input" name="email" type="email" maxlength="160" value="${L.esc(shop.email)}"></label><label class="field full">${L.t('address')}<input class="input" name="address" maxlength="220" value="${L.esc(shop.address)}"></label><label class="field full">${L.t('customCategories')}<textarea class="textarea" name="categories" maxlength="2500" aria-describedby="categories-help">${L.esc(S.state.categories.filter(x=>!C.CATEGORIES.includes(x)).join('\n'))}</textarea><span class="muted small" id="categories-help">${L.t('categoriesHelp')}</span></label><div class="full"><button class="btn primary">${L.t('saveSettings')}</button></div></form>`:tab==='subscription'?`<div class="form-grid"><div class="full"><h2>${L.t('subscriptionTab')}</h2><p class="muted small">${L.t('licenseDisclosure')}</p></div><div class="full license-summary"><strong>${L.t(L.license.plan==='free'?'free':L.license.plan==='repair-pro'?'pro':'proPlus')}</strong><span>${L.t(({inactive:'licenseInactive',active:'licenseActive',offline:'licenseOffline',expired:'licenseExpired','needs-online':'licenseNeedsOnline','clock-check':'licenseClock','update-required':'licenseUpdateRequired',invalid:'licenseInvalid'})[L.license.status]||'licenseInactive')}</span>${L.license.expiresOn?`<span>${L.esc(L.license.expiresOn)}</span>`:''}${L.license.accountEmail?`<span>${L.t('accountConnected')}: ${L.esc(L.license.accountEmail)}</span>`:''}</div>${!L.license.activated||L.license.plan==='free'||!L.license.accountEmail?`<form id="license-form" class="form-grid full">${L.accountFields()}${!L.license.activated||L.license.plan==='free'?`<label class="field full">${L.t('licenseCode')}<input class="input" name="code" maxlength="55" autocomplete="off" spellcheck="false" placeholder="REPAIR-…" required></label>`:''}<label class="check full"><input type="checkbox" name="consent" required>${L.t('licenseConsent')}</label><div class="full"><button class="btn primary" type="submit" ${L.license.storageAvailable?'':'disabled'}>${L.t(L.license.activated&&L.license.plan!=='free'?'reconnectAccount':'activateLicense')}</button></div>${!L.license.storageAvailable?`<p class="muted small full">${L.t('licenseStore')}</p>`:''}</form>`:''}<div class="quick-actions full">${L.license.activated?`<button class="btn" data-action="license-check">${L.t('checkLicense')}</button>`:''}${L.license.accountEmail?`<button class="btn" data-action="account-logout">${L.t('accountSignOut')}</button>`:''}${L.license.daysLeft!==null&&L.license.daysLeft<=7&&L.license.contact?.email?`<button class="btn primary" data-action="license-contact">${L.t('renewal')}</button>`:''}<button class="btn" data-page="plans">${L.t('plansTitle')}</button></div></div>`:tab==='data'?`<div class="form-grid"><div class="full"><h2>${L.t('backup')}</h2><p class="muted small" style="margin:6px 0 14px">${L.t('importWarning')}</p></div><div><button class="btn primary" data-action="export">${L.t('export')}</button><button class="btn" data-action="import">${L.t('import')}</button>${L.license.plan==='repair-pro-plus'?`<button class="btn" data-action="encrypted-export">${L.t('encryptedBackup')}</button>`:`<button class="btn" data-page="plans">${L.t('proPlus')}</button>`}<button class="btn" data-action="encrypted-import">${L.t('encryptedImport')}</button></div><p class="muted small full">${L.t('localOnly')}</p></div>`:`<div class="form-grid"><div class="full"><h2>${L.t('checkUpdate')}</h2><p class="muted small">${L.t('appVersion')}: ${window.REPAIR_CFG.version}</p></div><div class="full"><button class="btn primary" data-action="check-update">${L.t('checkUpdate')}</button><span id="update-status" class="muted small"></span></div><p class="muted small full">${L.t('autoUpdate')}</p></div>`}</article></div></section>`;};
L.render=()=>{L.renderNav();const main=document.getElementById('main');main.classList.remove('enter');let html=L.page==='home'?L.homePage():L.page==='orders'?L.ordersPage():L.page==='parts'?L.partsPage():L.page==='timeline'?L.timelinePage():L.page==='reports'?L.reportsPage():L.page==='plans'?L.plansPage():L.page==='settings'?L.settingsPage():L.page==='order'?L.detailPage():L.homePage();main.innerHTML=html;L.applyPrefs();if(L.page==='order')L.renderAttachments();};
L.renderAttachments=async()=>{const o=L.order(L.orderId),box=document.getElementById('order-attachments');if(!o||!box)return;if(!o.photos.length){box.innerHTML=`<p class="muted small">${L.t('evidence')} —</p>`;return;}box.innerHTML='';for(const p of o.photos){const item=document.createElement('div');item.className='attachment';item.title=p.name;const data=await host.attachment(p.id);if(data&&data.mime.startsWith('image/')){const img=document.createElement('img');img.alt=p.name;img.src=`data:${data.mime};base64,${data.data}`;item.append(img)}else item.textContent=p.name;const caption=document.createElement('span');caption.textContent=p.name;item.append(caption);box.append(item);}};
L.showSetup=()=>{L.modal(L.t('welcome'),`<img class="setup-mark" src="assets/koluva-repair-isotipo-color.svg" alt=""><p class="muted" style="margin-bottom:14px">${L.t('welcomeText')}</p><form id="setup-form" class="form-grid"><label class="field full">${L.t('shopName')}<input class="input" name="name" maxlength="120" required></label><label class="field">${L.t('shopType')}<select class="select" name="kind"><option value="repair-shop">Repair shop</option><option value="phone-repair">Phone repair</option><option value="computer-repair">Computer repair</option><option value="console-repair">Console repair</option><option value="general-repair">General repair</option></select></label><label class="field">${L.t('currency')}<select class="select" name="currency">${['ARS','USD','EUR','BRL','MXN','CLP','UYU'].map(x=>`<option ${x==='ARS'?'selected':''}>${x}</option>`).join('')}</select></label></form>`,[{label:L.t('continue'),submit:true,primary:true}]);};
L.showTour=(step=0)=>{const pieces=[[L.t('tourTitle'),L.t('tourText'),'orders'],[L.t('history'),L.t('correctionHint'),'timeline'],[L.t('backup'),L.t('localOnly'),'settings']];const x=pieces[step];L.modal(x[0],`<div class="tour-step"><img src="assets/koluva-repair-isotipo-color.svg" alt=""><p>${L.esc(x[1])}</p><div class="tour-dots">${pieces.map((_,i)=>`<span class="${i===step?'active':''}"></span>`).join('')}</div></div>`,[{label:L.t('tourSkip'),action:'tour-skip'},{label:step===pieces.length-1?L.t('continue'):L.t('tourNext'),action:`tour-${step+1}`,primary:true}]);};
L.editNote=()=>{L.modal(L.t('addDiagnosis'),`<form id="note-form"><label class="field">${L.t('note')}<textarea class="textarea" name="note" maxlength="3000" required></textarea></label></form>`,[{label:L.t('cancel'),action:'close'},{label:L.t('save'),submit:true,primary:true}]);};
L.assignPartForm=()=>{const parts=S.state.parts.filter(p=>!p.archived&&p.quantity>0);if(!parts.length){L.toast(L.t('noStock'));return;}L.modal(L.t('assignPart'),`<form id="assign-part-form"><label class="field">${L.t('partName')}<select class="select" name="partId">${parts.map(p=>`<option value="${p.id}">${L.esc(p.name)} (${p.quantity}) — ${L.money(p.price)}</option>`).join('')}</select></label><label class="field" style="margin-top:12px">${L.t('quantity')}<input class="input" type="number" min="0.01" step="0.01" value="1" name="quantity" required></label></form>`,[{label:L.t('cancel'),action:'close'},{label:L.t('save'),submit:true,primary:true}]);};
L.correctionForm=()=>{const o=L.order(L.orderId);L.modal(L.t('correction'),`<form id="correction-form"><label class="field">${L.t('history')}<select class="select" name="target">${o.events.map(e=>`<option value="${e.id}">${L.esc(e.title)} — ${L.date(e.at)}</option>`).join('')}</select></label><label class="field" style="margin-top:10px">${L.t('correction')}<textarea class="textarea" name="text" required maxlength="1200"></textarea></label><label class="field" style="margin-top:10px">${L.t('reason')}<textarea class="textarea" name="reason" required maxlength="800"></textarea></label><p class="muted small">${L.t('correctionHint')}</p></form>`,[{label:L.t('cancel'),action:'close'},{label:L.t('save'),submit:true,primary:true}]);};
L.quoteForm=()=>{L.modal(L.t('addEstimate'),`<form id="quote-form"><div id="quote-lines"><div class="quote-line"><input class="input" name="description" placeholder="${L.t('description')}" maxlength="180" required><input class="input" name="quantity" type="number" min="0.01" step="0.01" value="1" aria-label="${L.t('quantity')}"><input class="input" name="unitPrice" type="number" min="0" step="0.01" placeholder="${L.t('unitPrice')}" required></div></div><button type="button" class="btn small" data-action="quote-line">${L.icon('plus')}${L.t('addEstimate')}</button><label class="field" style="margin-top:12px">${L.t('note')}<textarea class="textarea" name="note" maxlength="1000"></textarea></label></form>`,[{label:L.t('cancel'),action:'close'},{label:L.t('save'),submit:true,primary:true}]);};
L.partForm=()=>{L.modal(L.t('addPart'),`<form id="part-form" class="form-grid"><label class="field full">${L.t('partName')}<input class="input" name="name" maxlength="140" required></label><label class="field">${L.t('sku')}<input class="input" name="sku" maxlength="80"></label><label class="field">${L.t('categoryPart')}<input class="input" name="category" maxlength="80"></label><label class="field">${L.t('stock')}<input class="input" name="quantity" type="number" min="0" step="1" value="0"></label><label class="field">${L.t('minimum')}<input class="input" name="minimum" type="number" min="0" step="1" value="0"></label><label class="field">${L.t('cost')}<input class="input" name="cost" type="number" min="0" step="0.01" value="0"></label><label class="field">${L.t('price')}<input class="input" name="price" type="number" min="0" step="0.01" value="0"></label></form>`,[{label:L.t('cancel'),action:'close'},{label:L.t('save'),submit:true,primary:true}]);};
L.setPaper=(format)=>{S.state.settings.paper=format;if(format==='custom'){S.state.settings.printWidth=Math.min(300,Math.max(40,Number(document.getElementById('print-width')?.value)||80));S.state.settings.printHeight=Math.min(600,Math.max(50,Number(document.getElementById('print-height')?.value)||120));}S.touch();};
L.print=async(o)=>{const t=L.t;const last=o.quoteVersions.at(-1);const events=[...o.events].reverse().map(e=>`<div class="print-rule"><div class="print-value">${L.esc(e.title)}</div><div class="print-label">${L.date(e.at)}${e.detail?' — '+L.esc(e.detail):''}</div></div>`).join('');const quote=last?`<div class="print-rule"><div class="print-value">${L.t('estimate')} v${last.version} — ${L.money(last.total)} (${L.t(last.status)})</div>${last.lines.map(x=>`<div class="print-value">${L.esc(x.description)} — ${x.quantity} × ${L.money(x.unitPrice)}</div>`).join('')}<div class="print-label">${last.decidedAt?`${L.t('printApproval')}: ${L.date(last.decidedAt)} — ${L.t(last.method==='in-person'?'inPerson':last.method==='phone'?'phoneMethod':last.method==='email'?'emailMethod':'otherMethod')}`:''}</div></div>`:'<div class="print-value">—</div>';const parts=o.parts.length?`<ul class="print-list">${o.parts.map(p=>`<li>${L.esc(p.name)} — ${p.quantity}</li>`).join('')}</ul>`:'<div class="print-value">—</div>';const evidence=[];for(const p of o.photos){const d=await host.attachment(p.id);if(d&&d.mime.startsWith('image/'))evidence.push(`<figure class="print-photo"><img src="data:${d.mime};base64,${d.data}" alt=""><figcaption>${L.esc(p.name)} — ${L.date(p.at||o.createdAt)}</figcaption></figure>`);else evidence.push(`<div class="print-rule">${L.esc(p.name)}</div>`);}const evidenceHtml=evidence.length?`<h2>${t('evidence')}</h2><div class="print-evidence">${evidence.join('')}</div>`:'';document.getElementById('print-root').dataset.size=S.state.settings.paper;document.getElementById('print-root').innerHTML=`<article class="print-sheet"><header><img src="assets/koluva-repair-isotipo-color.svg" alt=""><div><h1>${L.esc(S.state.shop.name||'Koluva Repair')}</h1><div>${L.esc(S.state.shop.address)} ${L.esc(S.state.shop.phone)}</div></div><div style="margin-left:auto;text-align:right"><strong>${L.esc(o.ticket)}</strong><div>${L.esc(L.status(o.status))}</div><div>${L.date(o.createdAt)}</div></div></header><section class="print-grid"><div class="print-rule"><div class="print-label">${t('printCustomer')}</div><div class="print-value">${L.esc(o.customer.name)}</div></div><div class="print-rule"><div class="print-label">${t('printContact')}</div><div class="print-value">${L.esc(o.customer.contact)}</div></div><div class="print-rule"><div class="print-label">${t('printDevice')}</div><div class="print-value">${L.esc(L.category(o.device.category))} ${L.esc(o.device.brand)} ${L.esc(o.device.model)} ${L.esc(o.device.serial)}</div></div><div class="print-rule"><div class="print-label">${t('dueDate')}</div><div class="print-value">${L.esc(o.dueDate||'—')}</div></div></section><h2>${t('printProblem')}</h2><div class="print-value">${L.esc(o.problem)}</div><h2>${t('printCondition')}</h2><div class="print-value">${L.esc(o.device.condition||'—')} ${o.device.accessories?' — '+L.esc(o.device.accessories):''}</div><h2>${t('diagnosis')}</h2><div class="print-value">${L.esc(o.diagnosis||'—')}</div><h2>${t('printEstimate')}</h2>${quote}<h2>${t('printParts')}</h2>${parts}${evidenceHtml}<h2>${t('printTimeline')}</h2>${events}<footer>${t('printFooter')} — ${L.esc(o.ticket)}</footer></article>`;const size=S.state.settings.paper,pageSize=size==='custom'?`${S.state.settings.printWidth}mm ${S.state.settings.printHeight}mm`:({a4:'A4',letter:'letter','58mm':'58mm auto','80mm':'80mm auto'}[size]||'A4');let st=document.getElementById('print-page-style');if(!st){st=document.createElement('style');st.id='print-page-style';document.head.append(st);}st.textContent=`@media print{@page{size:${pageSize};margin:0}}`;setTimeout(()=>window.print(),180);window.onafterprint=()=>{document.getElementById('print-root').innerHTML='';};};
let updateTimeout=null,updateInterval=null,updateGeneration=0,notifiedUpdate='';
L.scheduleUpdateChecks=()=>{updateGeneration++;clearTimeout(updateTimeout);clearInterval(updateInterval);if(!S.state?.settings?.autoUpdate)return;const generation=updateGeneration;updateTimeout=setTimeout(()=>{L.checkUpdate(true,generation);updateInterval=setInterval(()=>L.checkUpdate(true,generation),6*60*60*1000);},8000);};
L.checkUpdate=async(silent=false,generation=updateGeneration)=>{const label=document.getElementById('update-status');if(label&&!silent)label.textContent=L.t('saving');try{const r=await host.update.check();if(r.status==='available'){window.REPAIR_CFG.pendingVersion=r.manifest.version;if(silent){if(generation===updateGeneration&&S.state?.settings?.autoUpdate&&notifiedUpdate!==r.manifest.version){notifiedUpdate=r.manifest.version;L.toast(L.t('updateAvailable'));}}else{L.modal(L.t('updateAvailable'),`<p>${L.t('appVersion')} ${L.esc(r.manifest.version)}</p><p class="muted small">${L.esc(r.manifest.notes?.[L.lang()]||'')}</p>`,[{label:L.t('cancel'),action:'close'},{label:L.t('downloadUpdate'),action:'update-download',primary:true}]);}}else if(label&&!silent)label.textContent=L.t(r.status==='current'?'currentVersion':'updateUnpublished');}catch{if(label&&!silent)label.textContent=L.t('updateError');}};
L.updateDownload=async()=>{try{host.update.onProgress(p=>{const label=document.getElementById('update-status');if(label)label.textContent=L.t('downloadProgress',{pct:p.pct});});await host.update.download(window.REPAIR_CFG.pendingVersion);await S.flush();L.toast(L.t('installing'));await host.update.install();}catch(e){L.toast(L.err(e));}};
L.export=async()=>{const text=await S.exportBundle();if(await host.saveFile(`KoluvaRepair-Backup-${new Date().toISOString().slice(0,10)}.krepair`,text,'application/json'))L.toast(L.t('exported'));};
L.import=async()=>{if(!confirm(L.t('importWarning')))return;const ok=await S.importFile();if(ok){L.applyPrefs();L.render();L.toast(L.t('imported'));}};
L.encryptedExport=()=>L.modal(L.t('backupEncryptTitle'),`<form id="encrypted-backup-form"><label class="field">${L.t('backupPassword')}<input class="input" type="password" name="password" minlength="12" autocomplete="new-password" required></label><label class="field">${L.t('backupPasswordConfirm')}<input class="input" type="password" name="confirm" minlength="12" autocomplete="new-password" required></label></form>`,[{label:L.t('cancel'),action:'close'},{label:L.t('encryptedBackup'),submit:true,primary:true}]);
let encryptedBackupPending='';
L.encryptedImport=async()=>{if(!confirm(L.t('importWarning')))return;const file=await host.openFile();if(!file)return;encryptedBackupPending=file.text;L.modal(L.t('backupImportTitle'),`<form id="encrypted-import-form"><label class="field">${L.t('backupPassword')}<input class="input" type="password" name="password" minlength="12" autocomplete="current-password" required></label></form>`,[{label:L.t('cancel'),action:'close'},{label:L.t('encryptedImport'),submit:true,primary:true}]);};
L.attach=async()=>{const o=L.order(L.orderId);if(!o)return;const files=await host.attach();for(const f of files){o.photos.push(f);await C.addEvent(o,'evidence','Evidence attached',f.name,{fileId:f.id,mime:f.mime,size:f.size});}if(files.length){S.touch();L.render();}};

document.addEventListener('click',async e=>{const theme=e.target.closest('[data-theme-choice]');if(theme){S.state.settings.theme=theme.dataset.themeChoice;S.touch();L.applyPrefs();return;}const wc=e.target.closest('[data-win]');if(wc){host.win.cmd(wc.dataset.win);return;}if(e.target.closest('#website')){host.openExternal('https://koluva.com');return;}const setTab=e.target.closest('[data-settings-tab]');if(setTab){L.settingsTab=setTab.dataset.settingsTab;L.render();return;}const nav=e.target.closest('[data-page]');if(nav){L.go(nav.dataset.page);return;}const order=e.target.closest('[data-order]');if(order){L.go('order',order.dataset.order);return;}const act=e.target.closest('[data-action]');if(!act)return;try{switch(act.dataset.action){case'new-order':L.openNewOrder();break;case'new-part':L.partForm();break;case'assign-part':L.assignPartForm();break;case'note':L.editNote();break;case'correction':L.correctionForm();break;case'new-quote':L.quoteForm();break;case'quote-line':{const box=document.getElementById('quote-lines'),div=document.createElement('div');div.className='quote-line';div.innerHTML=`<input class="input" name="description" placeholder="${L.esc(L.t('description'))}" maxlength="180" required><input class="input" name="quantity" type="number" min="0.01" step="0.01" value="1" aria-label="${L.esc(L.t('quantity'))}"><input class="input" name="unitPrice" type="number" min="0" step="0.01" placeholder="${L.esc(L.t('unitPrice'))}" required><button type="button" class="icon-button remove-line" aria-label="${L.esc(L.t('cancel'))}" data-action="remove-line">${L.icon('close')}</button>`;box.append(div);break;}case'remove-line':act.closest('.quote-line').remove();break;case'attach':await L.attach();break;case'print':{const o=L.order(L.orderId);if(o)L.modal(L.t('format'),`<label class="field">${L.t('format')}<select class="select" id="print-format"><option value="a4">${L.t('sizeA4')}</option><option value="letter">${L.t('sizeLetter')}</option><option value="58mm">${L.t('size58')}</option><option value="80mm">${L.t('size80')}</option><option value="custom">${L.t('sizeCustom')}</option></select></label><div class="custom-paper" id="custom-paper" hidden><label class="field">${L.t('widthMm')}<input class="input" id="print-width" type="number" min="40" max="300" value="${S.state.settings.printWidth}"></label><label class="field">${L.t('heightMm')}<input class="input" id="print-height" type="number" min="50" max="600" value="${S.state.settings.printHeight}"></label></div>`,[{label:L.t('cancel'),action:'close'},{label:L.t('print'),action:'print-confirm',primary:true}]);break;}case'print-confirm':{const o=L.order(L.orderId);L.setPaper(document.getElementById('print-format').value);L.close();L.print(o);break;}case'export':await L.export();break;case'import':await L.import();break;case'check-update':await L.checkUpdate();break;case'update-download':{L.close();const v=window.REPAIR_CFG.pendingVersion;await host.update.download(v);await S.flush();await host.update.install();break;}case'contact':host.openExternal('mailto:koluvacorp@gmail.com?subject=Koluva%20Repair%20-%20planes');break;case'google-account':{const f=document.getElementById('license-form');if(!f?.elements.namedItem('accountTerms')?.checked){L.toast(L.t('googleTerms'));break;}await host.account.google({accepted:true});L.toast(L.t('googleStarted'));break;}case'account-legal':host.openExternal('https://koluva.com/book/terms');break;case'account-logout':await host.account.signOut();L.license=await host.license.info();L.render();L.toast(L.t('accountSignedOut'));break;case'license-check':await host.license.check();await L.loadLicense();L.render();L.toast(L.t('licenseActive'));break;case'license-contact':await host.license.contact();break;case'encrypted-export':if(L.license.plan!=='repair-pro-plus'){L.toast(L.t('limitReached'));break;}L.encryptedExport();break;case'encrypted-import':await L.encryptedImport();break;case'tour-skip':S.state.settings.tourDone=true;S.touch();L.close();break;default:if(act.dataset.action.startsWith('tour-')){const next=Number(act.dataset.action.slice(5));if(next<3)L.showTour(next);else{S.state.settings.tourDone=true;S.touch();L.close();}}}}catch(err){L.toast(L.err(err));}});
document.addEventListener('change',e=>{if(e.target.id==='print-format'){const box=document.getElementById('custom-paper');if(box)box.hidden=e.target.value!=='custom';}});
document.addEventListener('change',async e=>{const sel=e.target.closest('#status-select');if(sel){const o=L.order(L.orderId);if(o){await C.updateOrder(o,{status:sel.value},`Status: ${L.status(sel.value)}`);S.touch();L.render();L.toast(L.t('statusChanged'));}return;}const q=e.target.closest('#order-search');if(q){const term=q.value.toLocaleLowerCase();const rows=S.state.orders.filter(o=>[o.ticket,o.customer.name,o.customer.contact,o.device.brand,o.device.model].join(' ').toLocaleLowerCase().includes(term));document.getElementById('order-rows').innerHTML=L.orderRows(rows);return;}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id.endsWith('-form')&&!['general-settings','shop-settings'].includes(f.id))return;e.preventDefault();try{const d=new FormData(f);if(f.id==='license-form'){if(!L.license.accountEmail){const account=await host.account.signIn({email:String(d.get('accountEmail')||'').trim(),password:String(d.get('accountPassword')||''),confirmPassword:String(d.get('accountConfirmPassword')||''),create:d.has('createAccount'),accepted:d.has('accountTerms'),lang:L.lang()});if(account.needsConfirmation)throw Error('account-confirmation');L.license.accountEmail=account.email;}const code=String(d.get('code')||'').trim();L.license=code?await host.license.activate({code,consent:d.has('consent')}):await host.license.check();L.close();L.render();L.toast(L.t('licenseActive'));}else if(f.id==='encrypted-backup-form'){if(String(d.get('password')).length<12)throw Error('weak-backup-pass');if(d.get('password')!==d.get('confirm'))throw Error('password-mismatch');const text=await S.encryptedExport(d.get('password'));if(await host.saveFile(`KoluvaRepair-Encrypted-${new Date().toISOString().slice(0,10)}.krepair.enc`,text,'application/json'))L.toast(L.t('backupEncrypted'));L.close();}else if(f.id==='encrypted-import-form'){const ok=await S.importEncrypted(encryptedBackupPending,d.get('password'));encryptedBackupPending='';L.close();if(ok){L.applyPrefs();L.render();L.toast(L.t('backupDecrypted'));}}else if(f.id==='order-form'){const input=Object.fromEntries(d.entries());await C.createOrder(input,S.state,C.planLimits(L.license.plan));const created=S.state.orders[0];created.dueDate=input.dueDate||'';S.touch();L.close();L.go('order',created.id);L.toast(L.t('statusSaved'));}else if(f.id==='setup-form'){S.state.shop.name=C.clean(d.get('name'),120);S.state.shop.kind=d.get('kind');S.state.shop.currency=d.get('currency');S.touch();L.close();if(!S.state.settings.tourDone)L.showTour(0);else L.render();}else if(f.id==='note-form'){const o=L.order(L.orderId),note=C.clean(d.get('note'),3000);if(note){o.diagnosis=note;await C.addEvent(o,'note',L.t('diagnosis'),note);S.touch();L.close();L.render();}}else if(f.id==='correction-form'){const o=L.order(L.orderId);await C.addCorrection(o,d.get('target'),d.get('text'),d.get('reason'));S.touch();L.close();L.render();}else if(f.id==='quote-form'){const o=L.order(L.orderId),lines=[...f.querySelectorAll('.quote-line')].map(row=>({description:row.querySelector('[name=description]').value,quantity:row.querySelector('[name=quantity]').value,unitPrice:row.querySelector('[name=unitPrice]').value}));await C.addQuote(o,lines,d.get('note'));S.touch();L.close();L.render();}else if(f.id==='part-form'){await C.addPart(S.state,Object.fromEntries(d.entries()),C.planLimits(L.license.plan));S.touch();L.close();L.render();}else if(f.id==='assign-part-form'){const o=L.order(L.orderId);if(!o)throw Error('order-not-found');await C.usePart(S.state,o,d.get('partId'),d.get('quantity'));S.touch();L.close();L.render();}else if(f.id==='general-settings'){Object.assign(S.state.settings,{lang:d.get('lang'),theme:d.get('theme'),motion:d.get('motion'),currency:d.get('currency'),opening:d.has('opening'),autoUpdate:d.has('autoUpdate')});S.state.shop.currency=d.get('currency');S.touch();L.scheduleUpdateChecks();L.render();L.toast(L.t('statusSaved'));}else if(f.id==='shop-settings'){Object.assign(S.state.shop,{name:C.clean(d.get('name'),120),kind:C.clean(d.get('kind'),60),phone:C.clean(d.get('phone'),80),email:C.clean(d.get('email'),160),address:C.clean(d.get('address'),220)});S.state.categories=[...new Set([...C.CATEGORIES,...String(d.get('categories')||'').split(/\r?\n/).map(v=>C.clean(v,60)).filter(Boolean)])].slice(0,50);S.touch();L.applyPrefs();L.render();L.toast(L.t('statusSaved'));}}catch(err){L.toast(L.err(err));}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action=approve],[data-action=reject]');if(!b)return;const o=L.order(L.orderId),q=o?.quoteVersions.at(-1);if(!q)return;try{const decision=b.dataset.action==='approve'?'approved':'rejected';let method='in-person',note='';if(!confirm(`${L.t(decision)}?`))return;await C.recordApproval(o,q.id,decision,method,note);S.touch();L.render();}catch(err){L.toast(L.err(err));}});
document.addEventListener('click',e=>{const d=e.target.closest('[data-modal-action]');if(!d)return;const action=d.dataset.modalAction;if(action==='close')L.close();else if(action==='print-confirm'){const o=L.order(L.orderId);const format=document.getElementById('print-format');if(o&&format){L.setPaper(format.value);L.close();L.print(o);}}else if(action==='update-download'){const v=window.REPAIR_CFG.pendingVersion;host.update.download(v).then(()=>S.flush()).then(()=>host.update.install()).catch(err=>L.toast(L.err(err)));L.close();}else if(action.startsWith('tour-')){const next=Number(action.slice(5));if(next<3)L.showTour(next);else{S.state.settings.tourDone=true;S.touch();L.close();}}else if(action==='tour-skip'){S.state.settings.tourDone=true;S.touch();L.close();}});
document.getElementById('modal-close').addEventListener('click',L.close);document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget)L.close()});
document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='k'){e.preventDefault();L.go('orders');setTimeout(()=>document.getElementById('order-search')?.focus(),50);}if(!e.ctrlKey&&!e.altKey&&!e.metaKey&&!e.target.closest('input,textarea,select,dialog')){if(e.key.toLowerCase()==='n'){e.preventDefault();L.openNewOrder()}else if(/^[1-7]$/.test(e.key)){const row=NAV[Number(e.key)-1];if(row)L.go(row[0]);}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-order][tabindex="0"]')){e.preventDefault();L.go('order',e.target.dataset.order);}});
document.getElementById('nav').addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||!L.motionOn())return;const items=[...document.querySelectorAll('.nav-item')];items.forEach(el=>{const r=el.getBoundingClientRect(),d=Math.abs(e.clientY-(r.top+r.height/2));el.style.setProperty('--dock',(1+.22*Math.max(0,1-d/115)).toFixed(3));});});document.getElementById('nav').addEventListener('pointerleave',()=>document.querySelectorAll('.nav-item').forEach(x=>x.style.removeProperty('--dock')));
})();
